INSERT INTO plot_points (universe_slug, id, work_slug, character_id, arc_id, at, text) VALUES
  ('star-wars', 'yja-0', 'young-jedi-adventures', 'kai-brightstar', 'yja-tempel', 1, 'Beginnt seine Ausbildung im Jedi-Tempel des Hochrepublik-Zeitalters.'),
  ('star-wars', 'yja-1', 'young-jedi-adventures', 'kai-brightstar', 'yja-freundschaft', 5, 'Lernt, dass wahre Jedi-Stärke aus Zusammenhalt statt Alleingang kommt.'),
  ('star-wars', 'yja-2', 'young-jedi-adventures', 'lys-solay', 'yja-freundschaft', 3, 'Hilft einem verängstigten Wesen, sich der Gruppe anzuschließen.'),
  ('star-wars', 'yja-3', 'young-jedi-adventures', 'nubs', 'yja-tempel', 2, 'Sorgt trotz fehlender Worte für den Zusammenhalt der jungen Padawane.'),
  ('star-wars', 'acolyte-0', 'the-acolyte', 'mae', 'acolyte-schwestern', 1, 'Beginnt eine Mordserie an den Jedi, die einst ihr Zuhause zerstörten.'),
  ('star-wars', 'acolyte-1', 'the-acolyte', 'osha', 'acolyte-schwestern', 3, 'Wird fälschlich der Verbrechen ihrer verschollen geglaubten Zwillingsschwester verdächtigt.'),
  ('star-wars', 'acolyte-2', 'the-acolyte', 'sol', 'acolyte-jedi', 6, 'Gesteht Osha, was auf Brendok wirklich geschah.'),
  ('star-wars', 'acolyte-3', 'the-acolyte', 'qimir', 'acolyte-schatten', 7, 'Enttarnt sich als heimlicher Sith-Lehrer im Hintergrund.'),
  ('star-wars', 'acolyte-4', 'the-acolyte', 'osha', 'acolyte-schatten', 8, 'Wendet sich nach dem Verlust ihrer Schwester der dunklen Seite zu.'),
  ('star-wars', 'episode-iv-0', 'episode-iv', 'luke', 'iv-held', 18, 'Findet Leias Hilferuf im Speicher von R2-D2.'),
  ('star-wars', 'episode-iv-1', 'episode-iv', 'luke', 'iv-held', 35, 'Verliert sein Zuhause und schließt sich Obi-Wan an.'),
  ('star-wars', 'episode-iv-2', 'episode-iv', 'luke', 'iv-rebellion', 48, 'Sucht mit Obi-Wan in Mos Eisley einen Piloten.'),
  ('star-wars', 'episode-iv-3', 'episode-iv', 'luke', 'iv-imperium', 75, 'Befreit Leia aus dem Zellenblock des Todessterns.'),
  ('star-wars', 'episode-iv-4', 'episode-iv', 'luke', 'iv-rebellion', 112, 'Fliegt den entscheidenden Angriff auf den Todesstern.'),
  ('star-wars', 'episode-iv-5', 'episode-iv', 'leia', 'iv-rebellion', 2, 'Versteckt die gestohlenen Pläne in R2-D2.'),
  ('star-wars', 'episode-iv-6', 'episode-iv', 'leia', 'iv-imperium', 40, 'Hält im Verhör stand – trotz Drohung gegen Alderaan.'),
  ('star-wars', 'episode-iv-7', 'episode-iv', 'leia', 'iv-held', 78, 'Übernimmt bei der eigenen Rettung das Kommando.'),
  ('star-wars', 'episode-iv-8', 'episode-iv', 'leia', 'iv-rebellion', 118, 'Ehrt die Helden nach der Schlacht von Yavin.'),
  ('star-wars', 'episode-iv-9', 'episode-iv', 'han', 'iv-rebellion', 50, 'Nimmt den Flug nach Alderaan gegen hohen Lohn an.'),
  ('star-wars', 'episode-iv-10', 'episode-iv', 'han', 'iv-imperium', 55, 'Entkommt mit dem Falken der imperialen Blockade.'),
  ('star-wars', 'episode-iv-11', 'episode-iv', 'han', 'iv-held', 108, 'Kehrt im letzten Moment zur Schlacht zurück.'),
  ('star-wars', 'episode-iv-12', 'episode-iv', 'vader', 'iv-imperium', 4, 'Entert das Rebellenschiff und sucht die Pläne.'),
  ('star-wars', 'episode-iv-13', 'episode-iv', 'vader', 'iv-held', 88, 'Trifft seinen alten Meister wieder.'),
  ('star-wars', 'episode-iv-14', 'episode-iv', 'vader', 'iv-imperium', 110, 'Verfolgt die Angreifer im Graben persönlich.'),
  ('star-wars', 'episode-iv-15', 'episode-iv', 'obi-wan', 'iv-held', 30, 'Erzählt Luke von dessen Vater und dem Lichtschwert.'),
  ('star-wars', 'episode-iv-16', 'episode-iv', 'obi-wan', 'iv-rebellion', 60, 'Schaltet den Traktorstrahl des Todessterns ab.'),
  ('star-wars', 'episode-iv-17', 'episode-iv', 'obi-wan', 'iv-held', 88, 'Stellt sich Vader im Duell.'),
  ('star-wars', 'episode-iv-18', 'episode-iv', 'r2-d2', 'iv-rebellion', 8, 'Flieht mit den Plänen auf den Wüstenplaneten.'),
  ('star-wars', 'episode-iv-19', 'episode-iv', 'r2-d2', 'iv-held', 22, 'Macht sich allein auf die Suche nach Obi-Wan.'),
  ('star-wars', 'episode-iv-20', 'episode-iv', 'r2-d2', 'iv-rebellion', 105, 'Fliegt als Astromech hinter Luke in die Schlacht.'),
  ('star-wars', 'episode-iv-21', 'episode-iv', 'c-3po', 'iv-rebellion', 10, 'Landet mit R2-D2 in einer Rettungskapsel auf Tatooine.'),
  ('star-wars', 'episode-iv-22', 'episode-iv', 'c-3po', 'iv-imperium', 80, 'Hält im Kontrollraum die Stellung.'),
  ('star-wars', 'episode-iv-23', 'episode-iv', 'tarkin', 'iv-imperium', 38, 'Demonstriert die Macht der Station an Alderaan.'),
  ('star-wars', 'episode-iv-24', 'episode-iv', 'tarkin', 'iv-imperium', 114, 'Lehnt die Evakuierung der Station ab.'),
  ('star-wars', 'episode-iv-25', 'episode-iv', 'chewbacca', 'iv-rebellion', 50, 'Fliegt mit Han den Millennium Falken.'),
  ('star-wars', 'episode-iv-26', 'episode-iv', 'chewbacca', 'iv-imperium', 70, 'Spielt den Gefangenen, um in den Zellenblock zu kommen.'),
  ('star-wars', 'batch-0', 'bad-batch', 'hunter', 'batch-batch', 1, 'Übernimmt nach Order 66 das Kommando über die desorientierte Truppe.'),
  ('star-wars', 'batch-1', 'bad-batch', 'hunter', 'batch-imperium', 3, 'Lehnt die Umrüstung auf Kontroll-Chips ab und flieht mit dem Team.'),
  ('star-wars', 'batch-2', 'bad-batch', 'omega', 'batch-batch', 1, 'Schließt sich der Truppe als heimliches Klon-Mädchen an.'),
  ('star-wars', 'batch-3', 'bad-batch', 'omega', 'batch-rat', 8, 'Wird von Nala Se als genetisch besonders wertvoll identifiziert.'),
  ('star-wars', 'batch-4', 'bad-batch', 'crosshair', 'batch-imperium', 1, 'Bleibt dem Imperium treu und wird zum Gegenspieler seines eigenen Teams.'),
  ('star-wars', 'batch-5', 'bad-batch', 'crosshair', 'batch-imperium', 16, 'Bricht endgültig mit dem Imperium, nachdem er selbst zur Wegwerfware wird.'),
  ('star-wars', 'batch-6', 'bad-batch', 'nala-se', 'batch-rat', 3, 'Versucht, die Klonforschung vor imperialem Zugriff zu schützen.'),
  ('star-wars', 'tote-0', 'tales-of-the-empire', 'morgan-elsbeth', 'tote-inquisitorin', 1, 'Verliert ihre Heimat Dathomir an die Klonkriege und schwört Rache.'),
  ('star-wars', 'tote-1', 'tales-of-the-empire', 'morgan-elsbeth', 'tote-inquisitorin', 3, 'Steigt zur Handlangerin Thrawns und zur Magistratin von Corvus auf.'),
  ('star-wars', 'tote-2', 'tales-of-the-empire', 'barriss', 'tote-dathomir', 4, 'Verlässt nach ihrem Verrat den Jedi-Orden und sucht in der Dunkelheit neuen Sinn.'),
  ('star-wars', 'kenobi-0', 'obi-wan-kenobi', 'obi-wan', 'kenobi-obi-wan', 1, 'Lebt zurückgezogen auf Tatooine und wacht heimlich über den jungen Luke.'),
  ('star-wars', 'kenobi-1', 'obi-wan-kenobi', 'obi-wan', 'kenobi-obi-wan', 2, 'Reist nach Daiyu, um die entführte Leia zu retten.'),
  ('star-wars', 'kenobi-2', 'obi-wan-kenobi', 'obi-wan', 'kenobi-vader', 4, 'Stellt sich Vader zum ersten Mal seit Mustafar in einem verheerenden Duell.'),
  ('star-wars', 'kenobi-3', 'obi-wan-kenobi', 'obi-wan', 'kenobi-anakin', 6, 'Erkennt, dass in Vader nichts vom einstigen Anakin übrig ist – und lässt los.'),
  ('star-wars', 'kenobi-4', 'obi-wan-kenobi', 'leia-organa', 'kenobi-obi-wan', 1, 'Wird von Kopfgeldjägern der Dritten Schwester entführt.'),
  ('star-wars', 'kenobi-5', 'obi-wan-kenobi', 'leia-organa', 'kenobi-obi-wan', 3, 'Beginnt, dem widerwilligen Obi-Wan zu vertrauen.'),
  ('star-wars', 'kenobi-6', 'obi-wan-kenobi', 'vader', 'kenobi-anakin', 3, 'Lässt Reva wissen, dass er von Obi-Wans Überleben erfahren hat.'),
  ('star-wars', 'kenobi-7', 'obi-wan-kenobi', 'vader', 'kenobi-vader', 4, 'Setzt ein Dorf in Brand, um Obi-Wan aus der Deckung zu locken.'),
  ('star-wars', 'kenobi-8', 'obi-wan-kenobi', 'reva', 'kenobi-vader', 5, 'Enthüllt ihre wahre Absicht: Rache an Vader statt Loyalität.'),
  ('star-wars', 'kenobi-9', 'obi-wan-kenobi', 'reva', 'kenobi-vader', 6, 'Verschont den jungen Luke auf Tatooine und lässt von der Rache ab.'),
  ('star-wars', 'rebels-0', 'star-wars-rebels', 'ezra', 'rebels-ghost', 1, 'Wird von der Crew der Ghost aus dem Leben als Straßendieb auf Lothal geholt.'),
  ('star-wars', 'rebels-1', 'star-wars-rebels', 'ezra', 'rebels-erwachen', 15, 'Opfert sich, um Thrawn ins unbekannte Weltall zu verbannen.'),
  ('star-wars', 'rebels-2', 'star-wars-rebels', 'kanan', 'rebels-ghost', 1, 'Bildet Ezra heimlich als Jedi aus, ohne Orden oder Tempel.'),
  ('star-wars', 'rebels-3', 'star-wars-rebels', 'kanan', 'rebels-imperium', 12, 'Verliert im Kampf gegen die Inquisitoren sein Augenlicht.'),
  ('star-wars', 'rebels-4', 'star-wars-rebels', 'hera', 'rebels-erwachen', 5, 'Vereint verstreute Widerstandszellen zur organisierten Rebellion.'),
  ('star-wars', 'rebels-5', 'star-wars-rebels', 'thrawn', 'rebels-imperium', 10, 'Analysiert die Kunst und Taktik der Rebellen, um sie gezielt zu zerschlagen.'),
  ('star-wars', 'andor-0', 'andor', 'cassian', 'andor-cassian', 1, 'Sucht auf Ferrix Antworten zum Verschwinden seiner Schwester – und tötet zwei Corp-Wachen in Notwehr.'),
  ('star-wars', 'andor-1', 'andor', 'cassian', 'andor-rebellion', 3, 'Wird von Luthen Rael angeworben, nachdem er der ISB nur knapp entkommt.'),
  ('star-wars', 'andor-2', 'andor', 'cassian', 'andor-imperium', 8, 'Wird ohne fairen Prozess zu sechs Jahren Zwangsarbeit auf Narkina 5 verurteilt.'),
  ('star-wars', 'andor-3', 'andor', 'cassian', 'andor-rebellion', 10, 'Organisiert den Ausbruch aus dem Gefängniskomplex.'),
  ('star-wars', 'andor-4', 'andor', 'cassian', 'andor-cassian', 12, 'Kehrt nach Ferrix zurück und übernimmt bei Maarvas Beerdigung offen die Rolle des Rebellen.'),
  ('star-wars', 'andor-5', 'andor', 'mon-mothma', 'andor-rebellion', 4, 'Schleust unter dem Deckmantel der Wohltätigkeit Gelder zur Finanzierung der Rebellion.'),
  ('star-wars', 'andor-6', 'andor', 'mon-mothma', 'andor-imperium', 9, 'Manövriert sich im Senat gegen wachsendes Misstrauen ihres Umfelds und der ISB.'),
  ('star-wars', 'andor-7', 'andor', 'bix', 'andor-cassian', 2, 'Verschafft Cassian einen riskanten Deal mit einem Schmuggler.'),
  ('star-wars', 'andor-8', 'andor', 'bix', 'andor-imperium', 11, 'Wird von der ISB verhört und schwer gefoltert.'),
  ('star-wars', 'andor-9', 'andor', 'syril', 'andor-imperium', 1, 'Verfolgt eigenmächtig die Ermittlungen zum Doppelmord auf Ferrix, gegen den Willen seiner Vorgesetzten.'),
  ('star-wars', 'andor-10', 'andor', 'syril', 'andor-imperium', 9, 'Wird von der ISB rekrutiert, um Cassian auf Chandrila aufzuspüren.'),
  ('star-wars', 'totu-0', 'tales-of-the-underworld', 'ventress', 'totu-unterwelt', 1, 'Arbeitet als Kopfgeldjägerin an der Seite von Boba Fett auf einem riskanten Auftrag.'),
  ('star-wars', 'totu-1', 'tales-of-the-underworld', 'boba', 'totu-unterwelt', 3, 'Bekräftigt vor Ventress seinen Ruf als gnadenloser Kopfgeldjäger.'),
  ('star-wars', 'the-mandalorian-0', 'the-mandalorian', 'din', 'm-gilde', 1, 'Nimmt einen ungewöhnlichen Auftrag des Klienten an.'),
  ('star-wars', 'the-mandalorian-1', 'the-mandalorian', 'din', 'm-kind', 1, 'Findet sein Ziel – und es ist ein Kind.'),
  ('star-wars', 'the-mandalorian-2', 'the-mandalorian', 'din', 'm-gilde', 3, 'Liefert ab, bereut es und holt das Kind zurück.'),
  ('star-wars', 'the-mandalorian-3', 'the-mandalorian', 'din', 'm-kind', 4, 'Sucht auf Sorgan ein Versteck für das Kind.'),
  ('star-wars', 'the-mandalorian-4', 'the-mandalorian', 'din', 'm-gideon', 7, 'Kehrt nach Nevarro zurück, um den Klienten zu stellen.'),
  ('star-wars', 'the-mandalorian-5', 'the-mandalorian', 'din', 'm-kind', 8, 'Nimmt den Auftrag an, das Kind zu seinesgleichen zu bringen.'),
  ('star-wars', 'the-mandalorian-6', 'the-mandalorian', 'grogu', 'm-kind', 1, 'Wird im Lager der Nikto entdeckt.'),
  ('star-wars', 'the-mandalorian-7', 'the-mandalorian', 'grogu', 'm-kind', 2, 'Hebt mit der Macht einen Mudhorn an.'),
  ('star-wars', 'the-mandalorian-8', 'the-mandalorian', 'grogu', 'm-gideon', 7, 'Wird von Sturmtruppen entführt.'),
  ('star-wars', 'the-mandalorian-9', 'the-mandalorian', 'greef', 'm-gilde', 1, 'Vermittelt Din den Auftrag.'),
  ('star-wars', 'the-mandalorian-10', 'the-mandalorian', 'greef', 'm-gilde', 3, 'Führt die Gilde gegen Din an.'),
  ('star-wars', 'the-mandalorian-11', 'the-mandalorian', 'greef', 'm-gideon', 7, 'Bietet Din einen Deal an – mit Hintergedanken.'),
  ('star-wars', 'the-mandalorian-12', 'the-mandalorian', 'cara', 'm-kind', 4, 'Trifft Din auf Sorgan im Zweikampf.'),
  ('star-wars', 'the-mandalorian-13', 'the-mandalorian', 'cara', 'm-gideon', 7, 'Schließt sich dem Plan für Nevarro an.'),
  ('star-wars', 'the-mandalorian-14', 'the-mandalorian', 'gideon', 'm-gideon', 7, 'Umstellt die Cantina auf Nevarro.'),
  ('star-wars', 'the-mandalorian-15', 'the-mandalorian', 'gideon', 'm-gideon', 8, 'Taucht mit dem Dunkelschwert auf.'),
  ('star-wars', 'the-mandalorian-16', 'the-mandalorian', 'ig-11', 'm-gilde', 1, 'Wetteifert mit Din um dasselbe Ziel.'),
  ('star-wars', 'the-mandalorian-17', 'the-mandalorian', 'ig-11', 'm-kind', 8, 'Beschützt das Kind – umprogrammiert.'),
  ('star-wars', 'the-mandalorian-18', 'the-mandalorian', 'kuiil', 'm-kind', 1, 'Hilft Din, das Lager zu erreichen.'),
  ('star-wars', 'the-mandalorian-19', 'the-mandalorian', 'kuiil', 'm-kind', 2, 'Repariert das zerlegte Schiff.'),
  ('star-wars', 'the-mandalorian-20', 'the-mandalorian', 'kuiil', 'm-kind', 7, 'Bringt das Kind in Sicherheit.'),
  ('star-wars', 'boba-0', 'book-of-boba-fett', 'boba', 'boba-vergangenheit', 2, 'Wird von Tuskenräubern gefangen genommen und lernt ihre Lebensweise.'),
  ('star-wars', 'boba-1', 'book-of-boba-fett', 'boba', 'boba-thron', 1, 'Übernimmt Jabbas altes Territorium auf Tatooine.'),
  ('star-wars', 'boba-2', 'book-of-boba-fett', 'boba', 'boba-thron', 5, 'Muss sich gegen die Übernahmeversuche des Pyke-Syndikats behaupten.'),
  ('star-wars', 'boba-3', 'book-of-boba-fett', 'fennec', 'boba-thron', 1, 'Wird Bobas rechte Hand und Sicherheitschefin.'),
  ('star-wars', 'boba-4', 'book-of-boba-fett', 'fennec', 'boba-thron', 5, 'Verhandelt mit den Straßenbanden von Mos Espa um Unterstützung.'),
  ('star-wars', 'boba-5', 'book-of-boba-fett', 'din', 'boba-tatooine', 6, 'Hilft Boba im entscheidenden Kampf gegen die Pykes.'),
  ('star-wars', 'boba-6', 'book-of-boba-fett', 'cad-bane', 'boba-thron', 6, 'Fordert Boba im Duell heraus, im Auftrag der Pykes.'),
  ('star-wars', 'sc-0', 'skeleton-crew', 'wim', 'sc-kinder', 1, 'Findet mit Freunden ein vergrabenes altes Schiff und startet versehentlich in den Hyperraum.'),
  ('star-wars', 'sc-1', 'skeleton-crew', 'wim', 'sc-galaxis', 8, 'Kehrt mit neuem Blick auf seine ruhige Heimatwelt zurück.'),
  ('star-wars', 'sc-2', 'skeleton-crew', 'fern', 'sc-kinder', 2, 'Übernimmt in der Gruppe die Führungsrolle, als Erwachsene fehlen.'),
  ('star-wars', 'sc-3', 'skeleton-crew', 'jod', 'sc-jod', 3, 'Gibt sich den Kindern gegenüber als Jedi aus, um ihr Vertrauen zu gewinnen.'),
  ('star-wars', 'sc-4', 'skeleton-crew', 'jod', 'sc-jod', 7, 'Wird als Pirat und Betrüger entlarvt.'),
  ('star-wars', 'sc-5', 'skeleton-crew', 'sm-33', 'sc-galaxis', 1, 'Erkennt die Kinder fälschlich als seine ''Captains'' an.'),
  ('star-wars', 'ahsoka-0', 'ahsoka', 'ahsoka-tano', 'ahsoka-ahsoka', 1, 'Folgt einer alten Karte, die zum verschollenen Großadmiral Thrawn führen soll.'),
  ('star-wars', 'ahsoka-1', 'ahsoka', 'ahsoka-tano', 'ahsoka-empire', 7, 'Stellt sich Thrawn im fernen Weltall zum entscheidenden Duell.'),
  ('star-wars', 'ahsoka-2', 'ahsoka', 'sabine', 'ahsoka-ahsoka', 2, 'Wird von Ahsoka in den Wegen der Macht unterrichtet, gegen deren eigene Zweifel.'),
  ('star-wars', 'ahsoka-3', 'ahsoka', 'sabine', 'ahsoka-din-djarin', 5, 'Reist eigenmächtig ins Unbekannte Weltall, um Ezra zu retten.'),
  ('star-wars', 'ahsoka-4', 'ahsoka', 'din-ahsoka', 'ahsoka-din-djarin', 4, 'Verrät Ahsoka Sabines Aufenthaltsort – aus Verpflichtung, nicht Überzeugung.'),
  ('star-wars', 'ahsoka-5', 'ahsoka', 'thrawn-ahsoka', 'ahsoka-empire', 7, 'Kehrt mit einer neuen Flotte aus dem Exil zurück.'),
  ('star-wars', 'maul-0', 'maul-shadow-lord', 'maul', 'maul-schatten', 1, 'Baut im Verborgenen ein neues Verbrechensnetzwerk nach dem Fall seines alten Syndikats auf.'),
  ('star-wars', 'maul-1', 'maul-shadow-lord', 'maul', 'maul-rache', 5, 'Verfolgt weiter seine Obsession, die Skywalker-Blutlinie auszulöschen.'),
  ('star-wars', 'maul-2', 'maul-shadow-lord', 'ochi', 'maul-schatten', 3, 'Bietet Maul seine Dienste als Assassine an.'),
  ('star-wars', 'resistance-0', 'star-wars-resistance', 'kaz', 'resistance-kaz', 1, 'Wird als verdeckter Spion des Widerstands auf die Ölplattform Colossus geschickt.'),
  ('star-wars', 'resistance-1', 'star-wars-resistance', 'poe', 'resistance-kaz', 1, 'Rekrutiert Kaz für die geheime Aufklärungsmission gegen die Erste Ordnung.'),
  ('star-wars', 'resistance-2', 'star-wars-resistance', 'torra', 'resistance-erste-ordnung', 18, 'Verteidigt Colossus gegen den offenen Angriff der Ersten Ordnung.'),
  ('star-wars', 'resistance-3', 'star-wars-resistance', 'kaz', 'resistance-erste-ordnung', 21, 'Schließt sich offen dem Widerstand gegen die Erste Ordnung an.');
