INSERT INTO plot_points (universe_slug, id, work_slug, character_id, arc_id, at, text) VALUES
  ('mcu', 'pp-cm-1', 'captain-marvel', 'carol-cm', 'cm-erwachen', 30, 'Erinnert sich in Bruchstücken an ein früheres Leben als Kree-Kriegerin.'),
  ('mcu', 'pp-cm-2', 'captain-marvel', 'carol-cm', 'cm-skrulls', 90, 'Erkennt, dass die Kree sie belogen haben, und wendet sich gegen sie.'),
  ('mcu', 'pp-cm-3', 'captain-marvel', 'fury-cm', 'cm-skrulls', 20, 'Begegnet erstmals einer außerirdischen Bedrohung und verliert dabei ein Auge.'),
  ('mcu', 'pp-cm-4', 'captain-marvel', 'yon-rogg-cm', 'cm-erwachen', 10, 'Trainiert Carol als Starforce-Kriegerin und unterdrückt ihre wahre Kraft.'),
  ('mcu', 'pp-cafa-1', 'captain-america-first-avenger', 'steve-cafa', 'cafa-supersoldat', 20, 'Wird vom schmächtigen Freiwilligen zum Supersoldaten Captain America.'),
  ('mcu', 'pp-cafa-2', 'captain-america-first-avenger', 'steve-cafa', 'cafa-hydra', 110, 'Stürzt das Schiff der Hydra ins Eis, um New York zu retten.'),
  ('mcu', 'pp-cafa-3', 'captain-america-first-avenger', 'bucky-cafa', 'cafa-hydra', 80, 'Stürzt bei einem Hydra-Einsatz scheinbar in den Tod.'),
  ('mcu', 'pp-cafa-4', 'captain-america-first-avenger', 'red-skull-cafa', 'cafa-hydra', 90, 'Wird von der Macht des Tesserakts ausgelöscht.'),
  ('mcu', 'pp-im-1', 'iron-man', 'tony-im', 'im-hoehle', 20, 'Baut in einer Höhle in Afghanistan den ersten Iron-Man-Anzug.'),
  ('mcu', 'pp-im-2', 'iron-man', 'tony-im', 'im-verrat', 115, 'Enttarnt sich öffentlich als Iron Man.'),
  ('mcu', 'pp-im-3', 'iron-man', 'obadiah-im', 'im-verrat', 90, 'Verrät Tony und baut selbst eine Rüstung, um ihn zu töten.'),
  ('mcu', 'pp-im-4', 'iron-man', 'rhodey-im', 'im-hoehle', 40, 'Findet Tony nach der Rettung aus der Wüste als Erster.'),
  ('mcu', 'pp-hulk-1', 'the-incredible-hulk', 'bruce-hulk', 'hulk-flucht', 10, 'Flieht quer durch Südamerika, um seine Verwandlung zu kontrollieren.'),
  ('mcu', 'pp-hulk-2', 'the-incredible-hulk', 'bruce-hulk', 'hulk-abomination', 95, 'Besiegt als Hulk das noch monströsere Abomination in Harlem.'),
  ('mcu', 'pp-hulk-3', 'the-incredible-hulk', 'ross-hulk', 'hulk-flucht', 15, 'Jagt Banner mit dem Militär durch mehrere Länder.'),
  ('mcu', 'pp-hulk-4', 'the-incredible-hulk', 'blonsky-hulk', 'hulk-abomination', 85, 'Lässt sich freiwillig zum Abomination mutieren.'),
  ('mcu', 'pp-im2-1', 'iron-man-2', 'tony-im2', 'im2-vergiftung', 15, 'Vergiftet sich langsam selbst durch den Palladium-Kern seines Reaktors.'),
